def order(api, customer_id, *items):
    return api.orders.handle_create({"customer_id": customer_id,
                                     "items": [{"sku": s, "quantity": q} for s, q in items]})


def test_order_history_unknown_customer_is_404(shop):
    response = shop.insights.handle_order_history("nobody")
    assert response.status == 404
    assert response.body == {"error": "customer not found"}


def test_order_history_is_empty_for_customer_without_orders(shop):
    response = shop.insights.handle_order_history("c1")
    assert response.status == 200
    assert response.body == {"customer_id": "c1", "orders": []}


def test_order_history_is_newest_first_and_applies_discounts(shop):
    first = order(shop, "c1", ("BOOK", 1)).body["order_id"]
    second = order(shop, "c1", ("BOOK", 4)).body["order_id"]  # 10_000 subtotal, 10% off
    order(shop, "c2", ("PEN", 1))  # another customer's order must not appear

    response = shop.insights.handle_order_history("c1")

    assert response.status == 200
    assert response.body == {"customer_id": "c1", "orders": [
        {"order_id": second, "status": "placed", "total_cents": 9_000},
        {"order_id": first, "status": "placed", "total_cents": 2_500},
    ]}


def test_order_history_includes_cancelled_orders_with_summary_totals(shop):
    placed = order(shop, "c2", ("BOOK", 4)).body["order_id"]  # gold: 10_000 less 15%
    shop.orders.handle_cancel(placed)

    history = shop.insights.handle_order_history("c2").body["orders"]
    summary_total = shop.orders.handle_get(placed).body["total_cents"]

    assert history == [{"order_id": placed, "status": "cancelled", "total_cents": 8_500}]
    assert history[0]["total_cents"] == summary_total

