"""Customer insight endpoints for the account team."""

from __future__ import annotations

from typing import Any

from orders.application.errors import CustomerNotFound
from orders.application.order_service import OrderService
from orders.controllers.http import Response, not_found


class CustomerInsightsController:
    def __init__(self, service: OrderService) -> None:
        self._service = service

    def handle_order_history(self, customer_id: str) -> Response:
        """A customer's orders, newest first, with totals as reported by the order summary."""
        try:
            orders = self._service.list_for_customer(customer_id)
        except CustomerNotFound:
            return not_found("customer")
        history: list[dict[str, Any]] = [
            {"order_id": summary.order.order_id,
             "status": summary.order.status,
             "total_cents": summary.total_cents}
            for summary in (self._service.summarize(o) for o in reversed(orders))
        ]
        return Response(200, {"customer_id": customer_id, "orders": history})

    def handle_lifetime_value(self, customer_id: str) -> Response:
        """Count and total of a customer's orders that are not cancelled, at summary totals."""
        try:
            orders = self._service.list_for_customer(customer_id)
        except CustomerNotFound:
            return not_found("customer")
        totals = [self._service.summarize(o).total_cents
                  for o in orders if o.status != "cancelled"]
        return Response(200, {"customer_id": customer_id, "order_count": len(totals),
                              "lifetime_value_cents": sum(totals)})

