from __future__ import annotations

from typing import Any

from orders.application.errors import CustomerNotFound
from orders.application.order_service import OrderService
from orders.controllers.http import InvalidRequest, Response, bad_request, not_found, require_positive_int


class CustomerInsightsController:
    def __init__(self, service: OrderService) -> None:
        self._service = service

    def _lifetime_value(self, orders: list) -> tuple[int, int]:
        """Number of non-cancelled orders and their total, at summary totals."""
        totals = [self._service.summarize(o).total_cents for o in orders if o.status != "cancelled"]
        return len(totals), sum(totals)

    def handle_order_history(self, customer_id: str) -> Response:
        """A customer's orders, newest first, with totals as reported by the order summary."""
        try:
            orders = self._service.list_for_customer(customer_id)
        except CustomerNotFound:
            return not_found("customer")
        history: list[dict[str, Any]] = [
            {"order_id": summary.order.order_id,
             "status": summary.order.status,
             "total_cents": summary.total_cents}
            for summary in (self._service.summarize(o) for o in reversed(orders))
        ]
        return Response(200, {"customer_id": customer_id, "orders": history})

    def handle_lifetime_value(self, customer_id: str) -> Response:
        """Count and total of a customer's orders that are not cancelled, at summary totals."""
        try:
            orders = self._service.list_for_customer(customer_id)
        except CustomerNotFound:
            return not_found("customer")
        count, total = self._lifetime_value(orders)
        return Response(200, {"customer_id": customer_id, "order_count": count,
                              "lifetime_value_cents": total})

    def handle_top_customers(self, limit: Any) -> Response:
        """Customers ranked by lifetime value (highest first, then customer_id); zero-value customers omitted."""
        try:
            limit = require_positive_int(limit, "limit")
        except InvalidRequest as exc:
            return bad_request(exc)
        ranked = []
        for customer in self._service.list_customers():
            _, total = self._lifetime_value(self._service.list_for_customer(customer.customer_id))
            if total > 0:
                ranked.append((total, customer))
        ranked.sort(key=lambda pair: (-pair[0], pair[1].customer_id))
        return Response(200, {"customers": [
            {"customer_id": c.customer_id, "name": c.name, "lifetime_value_cents": total}
            for total, c in ranked[:limit]
        ]})

